package main

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"net/url"
	"os"
	"strings"
	"unicode/utf8"

	"github.com/stanimirivanov/argus/internal/performance/adapters/cli/requestcli"
	"github.com/stanimirivanov/argus/internal/performance/adapters/perfeng"
	"github.com/stanimirivanov/argus/internal/performance/requestintent"
	"github.com/stanimirivanov/argus/internal/postgres"
)

// Host-controlled approval is generated by an authenticated operator/CI process
// outside submitted input control. An absent write digest grants inspection only.
type cancellationApproval struct {
	Scope              requestintent.Scope `json:"scope"`
	Position           int64               `json:"position"`
	RequestSHA256      string              `json:"requestSha256"`
	CancellationSHA256 string              `json:"cancellationSha256,omitempty"`
}

type cancellationStorage interface {
	PendingRequests(context.Context, requestintent.Scope, int64, int) ([]requestintent.Pending, error)
	RequestCancellation(context.Context, requestintent.Scope, int64, requestintent.Cancellation, requestintent.CancellationVerifier) (bool, error)
	GetCancellation(context.Context, requestintent.Scope, int64, requestintent.CancellationVerifier) (requestintent.Cancellation, error)
}

func cancellationOperation(ctx context.Context, command requestcli.CancellationCommand) (requestcli.CancellationResult, error) {
	raw, err := requestcli.ReadCreationFile(os.Getenv("ARGUS_PERFORMANCE_CANCELLATION_APPROVAL_FILE"))
	if err != nil {
		return requestcli.CancellationResult{}, err
	}
	approval, err := cancellationPreflight(raw, command)
	if err != nil {
		return requestcli.CancellationResult{}, err
	}
	if err := ctx.Err(); err != nil {
		return requestcli.CancellationResult{}, err
	}
	runtime, err := postgres.OpenRuntime(ctx, os.Getenv("ARGUS_DATABASE_URL"))
	if err != nil {
		return requestcli.CancellationResult{}, err
	}
	defer runtime.Close()

	return cancellationStored(ctx, command, approval, runtime.Performance())
}

func cancellationPreflight(raw []byte, command requestcli.CancellationCommand) (cancellationApproval, error) {
	var a cancellationApproval
	if len(raw) > 16<<20 || !utf8.Valid(raw) || json.Unmarshal(raw, &a) != nil {
		return a, requestintent.ErrInvalid
	}
	canonical, err := json.Marshal(a)
	if err != nil || !bytes.Equal(bytes.TrimSpace(raw), canonical) || !requestintent.ValidScope(a.Scope) || a.Position <= 0 || a.Position != command.Position || !cancellationDigest(a.RequestSHA256) || (a.CancellationSHA256 != "" && !cancellationDigest(a.CancellationSHA256)) {
		return cancellationApproval{}, requestintent.ErrInvalid
	}
	for _, issuer := range []string{a.Scope.Issuer, a.Scope.PrincipalIssuer} {
		parsed, err := url.Parse(issuer)
		if err != nil || !parsed.IsAbs() || parsed.User != nil || parsed.RawQuery != "" || parsed.Fragment != "" {
			return cancellationApproval{}, requestintent.ErrInvalid
		}
	}
	if command.Record {
		m, err := perfeng.DecodeIntegration(command.Payload)
		if err != nil || m.Type != "dev.perfeng.integration.cancel-requested.v1" || a.CancellationSHA256 == "" {
			return cancellationApproval{}, requestintent.ErrInvalid
		}
		payload, err := perfeng.EncodeIntegration(m)
		if err != nil || cancellationHash(payload) != a.CancellationSHA256 {
			return cancellationApproval{}, requestintent.ErrInvalid
		}
	} else if len(command.Payload) != 0 {
		return cancellationApproval{}, requestintent.ErrInvalid
	}

	return a, nil
}

func cancellationStored(ctx context.Context, command requestcli.CancellationCommand, a cancellationApproval, store cancellationStorage) (requestcli.CancellationResult, error) {
	pending, err := store.PendingRequests(ctx, a.Scope, a.Position-1, 1)
	if err != nil {
		return requestcli.CancellationResult{}, err
	}
	if len(pending) != 1 || pending[0].After != a.Position {
		return requestcli.CancellationResult{}, requestintent.ErrNotFound
	}
	child := pending[0].Child
	original, err := perfeng.DecodeIntegration(child.Payload)
	if err != nil || !child.Valid() || child.SHA256 != a.RequestSHA256 || original.Data.Context.Principal != (perfeng.IntegrationIdentity{Issuer: a.Scope.PrincipalIssuer, ID: a.Scope.PrincipalID}) {
		return requestcli.CancellationResult{}, requestintent.ErrInvalid
	}
	var intent requestintent.Cancellation
	created := false
	if command.Record {
		intent, err = perfeng.BindCancellation(child.Payload, command.Payload)
		if err != nil || cancellationHash(intent.Data().Payload) != a.CancellationSHA256 {
			return requestcli.CancellationResult{}, requestintent.ErrInvalid
		}
		if err := ctx.Err(); err != nil {
			return requestcli.CancellationResult{}, err
		}
		created, err = store.RequestCancellation(ctx, a.Scope, a.Position, intent, perfeng.BindCancellation)
	} else {
		intent, err = store.GetCancellation(ctx, a.Scope, a.Position, perfeng.BindCancellation)
	}
	if err != nil {
		return requestcli.CancellationResult{}, err
	}
	checked, err := perfeng.BindCancellation(child.Payload, intent.Data().Payload)
	if err != nil || checked.Fingerprint() != intent.Fingerprint() || (a.CancellationSHA256 != "" && cancellationHash(intent.Data().Payload) != a.CancellationSHA256) {
		return requestcli.CancellationResult{}, requestintent.ErrUnavailable
	}

	return requestcli.CancellationResult{Scope: a.Scope, Intent: intent, Created: created}, nil
}

func cancellationHash(raw []byte) string {
	digest := sha256.Sum256(raw)
	return hex.EncodeToString(digest[:])
}

func cancellationDigest(value string) bool {
	raw, err := hex.DecodeString(value)
	return err == nil && len(raw) == 32 && strings.ToLower(value) == value
}
